import re,glob,os
files=sorted(glob.glob('draft/*.md'))+sorted(glob.glob('figures/*.md'))
bad=re.compile(r'(TODO|TBD|placeholder|\[insert|XXX|draftsperson|drafter|illustrator|attorney|confirm with|to be determined|—)',re.I)
for f in files:
    t=open(f).read()
    for i,l in enumerate(t.splitlines(),1):
        m=bad.search(l)
        if m: print("MARKER",f,i,m.group(0))
# numeral table
tab={}
for l in open('draft/numerals.md'):
    m=re.match(r'\|\s*(\d+)\s*\|\s*(.+?)\s*\|',l)
    if m: tab[m.group(1)]=m.group(2)
print("table",len(tab),sorted(tab,key=int))
used=set()
for f in sorted(glob.glob('draft/0*.md')):
    for n in re.findall(r'\b(\d{1,3})\b',open(f).read()):
        if n in tab: used.add(n)
print("unused in text:",sorted(set(tab)-used,key=int))
for f in sorted(glob.glob('figures/*.md')):
    t=open(f).read()
    listed=set(re.findall(r'^- (\d+)$',t,re.M))
    inline=set(re.findall(r'\b(\d{1,3})\b',t.split('**Numerals appearing')[0]))
    inline={n for n in inline if n in tab}
    print(os.path.basename(f), "len",len(t), "listed",sorted(listed,key=int),
          "inline-not-listed",sorted(inline-listed,key=int),
          "listed-not-inline",sorted(listed-inline,key=int),
          "not-in-table",sorted(listed-set(tab),key=int))
